    public override ThreadStatus? Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        using var document = JsonDocument.ParseValue(ref reader);
        var root = document.RootElement;
        var tag = root.ValueKind == JsonValueKind.Object && root.TryGetProperty("type", out var t)
            && t.ValueKind == JsonValueKind.String ? t.GetString() ?? "" : "";
        try
        {
            return tag switch
            {
                "notLoaded" => root.Deserialize(ProtocolJsonContext.Default.NotLoadedThreadStatus),
                "idle" => root.Deserialize(ProtocolJsonContext.Default.IdleThreadStatus),
                "systemError" => root.Deserialize(ProtocolJsonContext.Default.SystemErrorThreadStatus),
                "active" => root.Deserialize(ProtocolJsonContext.Default.ActiveThreadStatus),
