            case NotLoadedThreadStatus v:
                WriteVariant(writer, value.Type, JsonSerializer.SerializeToElement(v, ProtocolJsonContext.Default.NotLoadedThreadStatus));
                break;
            case IdleThreadStatus v:
                WriteVariant(writer, value.Type, JsonSerializer.SerializeToElement(v, ProtocolJsonContext.Default.IdleThreadStatus));
                break;
            case SystemErrorThreadStatus v:
                WriteVariant(writer, value.Type, JsonSerializer.SerializeToElement(v, ProtocolJsonContext.Default.SystemErrorThreadStatus));
                break;
            case ActiveThreadStatus v:
