internal sealed class CommandActionJsonConverter : JsonConverter<CommandAction>
{
    public override CommandAction? Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        using var document = JsonDocument.ParseValue(ref reader);
        var root = document.RootElement;
        var tag = root.ValueKind == JsonValueKind.Object && root.TryGetProperty("type", out var t)
            && t.ValueKind == JsonValueKind.String ? t.GetString() ?? "" : "";
        try
        {
            return tag switch
            {
                "read" => root.Deserialize(ProtocolJsonContext.Default.ReadCommandAction),
                "listFiles" => root.Deserialize(ProtocolJsonContext.Default.ListFilesCommandAction),
                "search" => root.Deserialize(ProtocolJsonContext.Default.SearchCommandAction),
                "unknown" => root.Deserialize(ProtocolJsonContext.Default.UnknownCommandAction),
                _ => new UnrecognizedCommandAction(tag, root.Clone()),
            };
        }
        catch (JsonException)
        {
            // 認得的變體卻缺欄位或型別不符：多半是協定改版，當成不認得的變體保留原始 JSON
            return new UnrecognizedCommandAction(tag, root.Clone());
        }
    }

    public override void Write(Utf8JsonWriter writer, CommandAction value, JsonSerializerOptions options)
    {
        switch (value)
        {
            case ReadCommandAction v:
                WriteVariant(writer, value.Type, JsonSerializer.SerializeToElement(v, ProtocolJsonContext.Default.ReadCommandAction));
                break;
            case ListFilesCommandAction v:
                WriteVariant(writer, value.Type, JsonSerializer.SerializeToElement(v, ProtocolJsonContext.Default.ListFilesCommandAction));
                break;
            case SearchCommandAction v:
                WriteVariant(writer, value.Type, JsonSerializer.SerializeToElement(v, ProtocolJsonContext.Default.SearchCommandAction));
                break;
            case UnknownCommandAction v:
                WriteVariant(writer, value.Type, JsonSerializer.SerializeToElement(v, ProtocolJsonContext.Default.UnknownCommandAction));
                break;
            case UnrecognizedCommandAction v:
                v.Raw.WriteTo(writer);
                break;
            default:
                throw new JsonException($"無法序列化 {value.GetType()}。");
        }
    }

    // 辨識欄位放第一個，後面接變體自己的欄位
    private static void WriteVariant(Utf8JsonWriter writer, string tag, JsonElement properties)
    {
        writer.WriteStartObject();
        writer.WriteString("type", tag);
        foreach (var property in properties.EnumerateObject())
        {
            property.WriteTo(writer);
        }

        writer.WriteEndObject();
    }
}

