internal sealed class WebSearchActionJsonConverter : JsonConverter<WebSearchAction>
{
    public override WebSearchAction? Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        using var document = JsonDocument.ParseValue(ref reader);
        var root = document.RootElement;
        var tag = root.ValueKind == JsonValueKind.Object && root.TryGetProperty("type", out var t)
            && t.ValueKind == JsonValueKind.String ? t.GetString() ?? "" : "";
        try
        {
            return tag switch
            {
                "search" => root.Deserialize(ProtocolJsonContext.Default.SearchWebSearchAction),
                "openPage" => root.Deserialize(ProtocolJsonContext.Default.OpenPageWebSearchAction),
                "findInPage" => root.Deserialize(ProtocolJsonContext.Default.FindInPageWebSearchAction),
                "other" => root.Deserialize(ProtocolJsonContext.Default.OtherWebSearchAction),
                _ => new UnknownWebSearchAction(tag, root.Clone()),
            };
        }
        catch (JsonException)
        {
            // 認得的變體卻缺欄位或型別不符：多半是協定改版，當成不認得的變體保留原始 JSON
            return new UnknownWebSearchAction(tag, root.Clone());
        }
    }

    public override void Write(Utf8JsonWriter writer, WebSearchAction value, JsonSerializerOptions options)
    {
        switch (value)
        {
            case SearchWebSearchAction v:
                WriteVariant(writer, value.Type, JsonSerializer.SerializeToElement(v, ProtocolJsonContext.Default.SearchWebSearchAction));
                break;
            case OpenPageWebSearchAction v:
                WriteVariant(writer, value.Type, JsonSerializer.SerializeToElement(v, ProtocolJsonContext.Default.OpenPageWebSearchAction));
                break;
            case FindInPageWebSearchAction v:
                WriteVariant(writer, value.Type, JsonSerializer.SerializeToElement(v, ProtocolJsonContext.Default.FindInPageWebSearchAction));
                break;
            case OtherWebSearchAction v:
                WriteVariant(writer, value.Type, JsonSerializer.SerializeToElement(v, ProtocolJsonContext.Default.OtherWebSearchAction));
                break;
            case UnknownWebSearchAction v:
                v.Raw.WriteTo(writer);
                break;
            default:
                throw new JsonException($"無法序列化 {value.GetType()}。");
        }
    }

    // 辨識欄位放第一個，後面接變體自己的欄位
    private static void WriteVariant(Utf8JsonWriter writer, string tag, JsonElement properties)
    {
        writer.WriteStartObject();
        writer.WriteString("type", tag);
        foreach (var property in properties.EnumerateObject())
        {
            property.WriteTo(writer);
        }

        writer.WriteEndObject();
    }
}

