/// <summary>這個 SDK 不認得的 <see cref="SandboxPolicy"/> 變體；原始 JSON 在 <see cref="Raw"/>。</summary>
public sealed record UnknownSandboxPolicy : SandboxPolicy
{
    internal UnknownSandboxPolicy(string type, JsonElement raw)
    {
        Type = type;
        Raw = raw;
    }

    /// <inheritdoc/>
    [JsonIgnore]
    public override string Type { get; }

    /// <summary>原始 JSON。</summary>
    [JsonIgnore]
    public JsonElement Raw { get; }
}

internal sealed class SandboxPolicyJsonConverter : JsonConverter<SandboxPolicy>
{
    public override SandboxPolicy? Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        using var document = JsonDocument.ParseValue(ref reader);
        var root = document.RootElement;
        var tag = root.ValueKind == JsonValueKind.Object && root.TryGetProperty("type", out var t)
            && t.ValueKind == JsonValueKind.String ? t.GetString() ?? "" : "";
        try
        {
            return tag switch
            {
                "dangerFullAccess" => root.Deserialize(ProtocolJsonContext.Default.DangerFullAccessSandboxPolicy),
                "readOnly" => root.Deserialize(ProtocolJsonContext.Default.ReadOnlySandboxPolicy),
                "externalSandbox" => root.Deserialize(ProtocolJsonContext.Default.ExternalSandboxSandboxPolicy),
                "workspaceWrite" => root.Deserialize(ProtocolJsonContext.Default.WorkspaceWriteSandboxPolicy),
                _ => new UnknownSandboxPolicy(tag, root.Clone()),
            };
        }
        catch (JsonException)
        {
            // 認得的變體卻缺欄位或型別不符：多半是協定改版，當成不認得的變體保留原始 JSON
            return new UnknownSandboxPolicy(tag, root.Clone());
        }
    }

    public override void Write(Utf8JsonWriter writer, SandboxPolicy value, JsonSerializerOptions options)
    {
        switch (value)
        {
            case DangerFullAccessSandboxPolicy v:
                WriteVariant(writer, value.Type, JsonSerializer.SerializeToElement(v, ProtocolJsonContext.Default.DangerFullAccessSandboxPolicy));
                break;
            case ReadOnlySandboxPolicy v:
                WriteVariant(writer, value.Type, JsonSerializer.SerializeToElement(v, ProtocolJsonContext.Default.ReadOnlySandboxPolicy));
                break;
            case ExternalSandboxSandboxPolicy v:
                WriteVariant(writer, value.Type, JsonSerializer.SerializeToElement(v, ProtocolJsonContext.Default.ExternalSandboxSandboxPolicy));
                break;
            case WorkspaceWriteSandboxPolicy v:
                WriteVariant(writer, value.Type, JsonSerializer.SerializeToElement(v, ProtocolJsonContext.Default.WorkspaceWriteSandboxPolicy));
                break;
            case UnknownSandboxPolicy v:
                v.Raw.WriteTo(writer);
                break;
            default:
                throw new JsonException($"無法序列化 {value.GetType()}。");
        }
    }

    // 辨識欄位放第一個，後面接變體自己的欄位
    private static void WriteVariant(Utf8JsonWriter writer, string tag, JsonElement properties)
    {
        writer.WriteStartObject();
        writer.WriteString("type", tag);
        foreach (var property in properties.EnumerateObject())
        {
            property.WriteTo(writer);
        }

        writer.WriteEndObject();
    }
}

