public sealed record UnknownThreadRealtimeItem : ThreadRealtimeItem
{
    internal UnknownThreadRealtimeItem(string type, JsonElement raw)
    {
        Type = type;
        Raw = raw;
    }

    /// <inheritdoc/>
    [JsonIgnore]
    public override string Type { get; }

    /// <summary>原始 JSON。</summary>
    [JsonIgnore]
    public JsonElement Raw { get; }
}

internal sealed class ThreadRealtimeItemJsonConverter : JsonConverter<ThreadRealtimeItem>
{
    public override ThreadRealtimeItem? Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        using var document = JsonDocument.ParseValue(ref reader);
        var root = document.RootElement;
        var tag = root.ValueKind == JsonValueKind.Object && root.TryGetProperty("type", out var t)
            && t.ValueKind == JsonValueKind.String ? t.GetString() ?? "" : "";
        try
        {
            return tag switch
            {
                "realtimeSessionStarted" => root.Deserialize(ProtocolJsonContext.Default.RealtimeSessionStartedThreadRealtimeItem),
                "transcriptSegment" => root.Deserialize(ProtocolJsonContext.Default.TranscriptSegmentThreadRealtimeItem),
                "bemItemPromoted" => root.Deserialize(ProtocolJsonContext.Default.BemItemPromotedThreadRealtimeItem),
                "realtimeSessionClosed" => root.Deserialize(ProtocolJsonContext.Default.RealtimeSessionClosedThreadRealtimeItem),
                _ => new UnknownThreadRealtimeItem(tag, root.Clone()),
            };
        }
        catch (JsonException)
        {
            // 認得的變體卻缺欄位或型別不符：多半是協定改版，當成不認得的變體保留原始 JSON
            return new UnknownThreadRealtimeItem(tag, root.Clone());
        }
    }

    public override void Write(Utf8JsonWriter writer, ThreadRealtimeItem value, JsonSerializerOptions options)
    {
        switch (value)
        {
            case RealtimeSessionStartedThreadRealtimeItem v:
                WriteVariant(writer, value.Type, JsonSerializer.SerializeToElement(v, ProtocolJsonContext.Default.RealtimeSessionStartedThreadRealtimeItem));
                break;
            case TranscriptSegmentThreadRealtimeItem v:
                WriteVariant(writer, value.Type, JsonSerializer.SerializeToElement(v, ProtocolJsonContext.Default.TranscriptSegmentThreadRealtimeItem));
                break;
            case BemItemPromotedThreadRealtimeItem v:
                WriteVariant(writer, value.Type, JsonSerializer.SerializeToElement(v, ProtocolJsonContext.Default.BemItemPromotedThreadRealtimeItem));
                break;
            case RealtimeSessionClosedThreadRealtimeItem v:
                WriteVariant(writer, value.Type, JsonSerializer.SerializeToElement(v, ProtocolJsonContext.Default.RealtimeSessionClosedThreadRealtimeItem));
                break;
            case UnknownThreadRealtimeItem v:
                v.Raw.WriteTo(writer);
                break;
            default:
                throw new JsonException($"無法序列化 {value.GetType()}。");
        }
    }

    // 辨識欄位放第一個，後面接變體自己的欄位
    private static void WriteVariant(Utf8JsonWriter writer, string tag, JsonElement properties)
    {
        writer.WriteStartObject();
        writer.WriteString("type", tag);
        foreach (var property in properties.EnumerateObject())
        {
            property.WriteTo(writer);
        }

        writer.WriteEndObject();
    }
}

