}

/// <summary>這個 SDK 不認得的 <see cref="McpServerElicitationRequestParams"/> 變體；原始 JSON 在 <see cref="Raw"/>。</summary>
public sealed record UnknownMcpServerElicitationRequestParams : McpServerElicitationRequestParams
{
    internal UnknownMcpServerElicitationRequestParams(string mode, JsonElement raw)
    {
        Mode = mode;
        Raw = raw;
    }

    /// <inheritdoc/>
