}

internal sealed class McpServerElicitationRequestParamsJsonConverter : JsonConverter<McpServerElicitationRequestParams>
{
    public override McpServerElicitationRequestParams? Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        using var document = JsonDocument.ParseValue(ref reader);
        var root = document.RootElement;
        var tag = root.ValueKind == JsonValueKind.Object && root.TryGetProperty("mode", out var t)
            && t.ValueKind == JsonValueKind.String ? t.GetString() ?? "" : "";
        try
        {
            return tag switch
            {
                "form" => root.Deserialize(ProtocolJsonContext.Default.FormMcpServerElicitationRequestParams),
                "openai/form" => root.Deserialize(ProtocolJsonContext.Default.OpenaiFormMcpServerElicitationRequestParams),
                "openaiForm" => root.Deserialize(ProtocolJsonContext.Default.OpenaiFormMcpServerElicitationRequestParams2),
                "url" => root.Deserialize(ProtocolJsonContext.Default.UrlMcpServerElicitationRequestParams),
                _ => new UnknownMcpServerElicitationRequestParams(tag, root.Clone()),
            };
        }
        catch (JsonException)
        {
            // 認得的變體卻缺欄位或型別不符：多半是協定改版，當成不認得的變體保留原始 JSON
            return new UnknownMcpServerElicitationRequestParams(tag, root.Clone());
        }
    }

    public override void Write(Utf8JsonWriter writer, McpServerElicitationRequestParams value, JsonSerializerOptions options)
    {
        switch (value)
        {
            case FormMcpServerElicitationRequestParams v:
                WriteVariant(writer, value.Mode, JsonSerializer.SerializeToElement(v, ProtocolJsonContext.Default.FormMcpServerElicitationRequestParams));
                break;
            case OpenaiFormMcpServerElicitationRequestParams v:
                WriteVariant(writer, value.Mode, JsonSerializer.SerializeToElement(v, ProtocolJsonContext.Default.OpenaiFormMcpServerElicitationRequestParams));
                break;
            case OpenaiFormMcpServerElicitationRequestParams2 v:
                WriteVariant(writer, value.Mode, JsonSerializer.SerializeToElement(v, ProtocolJsonContext.Default.OpenaiFormMcpServerElicitationRequestParams2));
                break;
            case UrlMcpServerElicitationRequestParams v:
                WriteVariant(writer, value.Mode, JsonSerializer.SerializeToElement(v, ProtocolJsonContext.Default.UrlMcpServerElicitationRequestParams));
                break;
            case UnknownMcpServerElicitationRequestParams v:
                v.Raw.WriteTo(writer);
                break;
            default:
                throw new JsonException($"無法序列化 {value.GetType()}。");
        }
    }

    // 辨識欄位放第一個，後面接變體自己的欄位
    private static void WriteVariant(Utf8JsonWriter writer, string tag, JsonElement properties)
    {
        writer.WriteStartObject();
        writer.WriteString("mode", tag);
        foreach (var property in properties.EnumerateObject())
        {
            property.WriteTo(writer);
        }

        writer.WriteEndObject();
    }
}

