                break;
            case ChatgptDeviceCodeLoginAccountResponse v:
                WriteVariant(writer, value.Type, JsonSerializer.SerializeToElement(v, ProtocolJsonContext.Default.ChatgptDeviceCodeLoginAccountResponse));
                break;
            case ChatgptAuthTokensLoginAccountResponse v:
                WriteVariant(writer, value.Type, JsonSerializer.SerializeToElement(v, ProtocolJsonContext.Default.ChatgptAuthTokensLoginAccountResponse));
                break;
            case AmazonBedrockLoginAccountResponse v:
                WriteVariant(writer, value.Type, JsonSerializer.SerializeToElement(v, ProtocolJsonContext.Default.AmazonBedrockLoginAccountResponse));
                break;
            case UnknownLoginAccountResponse v:
                v.Raw.WriteTo(writer);
                break;
            default:
                throw new JsonException($"無法序列化 {value.GetType()}。");
        }
    }

    // 辨識欄位放第一個，後面接變體自己的欄位
    private static void WriteVariant(Utf8JsonWriter writer, string tag, JsonElement properties)
    {
        writer.WriteStartObject();
        writer.WriteString("type", tag);
        foreach (var property in properties.EnumerateObject())
        {
            property.WriteTo(writer);
        }

        writer.WriteEndObject();
    }
}

